#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
constexpr i64 MOD = 1000000007;

template<typename T>
class Matrix {
public:
    vector<vector<T>> M;

    Matrix() = default;

    Matrix(size_t r, size_t c) : M(r, vector<T>(c, 0)) {}

    Matrix(size_t n) : M(n, vector<T>(n, 0)) {}

    size_t rows() const { return M.size(); }
    size_t cols() const { return M.empty() ? 0 : M[0].size(); }

    const vector<T>& operator[](size_t idx) const { return M[idx]; }
    vector<T>& operator[](size_t idx) { return M[idx]; }

    static Matrix I(size_t n) {
        Matrix res(n);
        for (size_t i = 0; i < n; ++i) res[i][i] = 1;
        return res;
    }

    Matrix& operator+=(const Matrix& other) {
        assert(rows() == other.rows() && cols() == other.cols());
        for (size_t i = 0; i < rows(); ++i)
            for (size_t j = 0; j < cols(); ++j)
                M[i][j] = (M[i][j] + other[i][j]) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        assert(rows() == other.rows() && cols() == other.cols());
        for (size_t i = 0; i < rows(); ++i)
            for (size_t j = 0; j < cols(); ++j)
                M[i][j] = (M[i][j] - other[i][j] + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        size_t r = rows(), c = other.cols(), m = cols();
        assert(m == other.rows());
        vector<vector<T>> tmp(r, vector<T>(c, 0));
        for (size_t i = 0; i < r; ++i)
            for (size_t k = 0; k < m; ++k)
                for (size_t j = 0; j < c; ++j)
                    tmp[i][j] = (tmp[i][j] + M[i][k] * other[k][j]) % MOD;
        M = move(tmp);
        return *this;
    }

    Matrix& operator^=(i64 exp) {
        Matrix res = I(rows());
        Matrix base = *this;
        while (exp > 0) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        M = move(res.M);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { Matrix t(*this); t += other; return t; }
    Matrix operator-(const Matrix& other) const { Matrix t(*this); t -= other; return t; }
    Matrix operator*(const Matrix& other) const { Matrix t(*this); t *= other; return t; }
    Matrix operator^(i64 exp) const { Matrix t(*this); t ^= exp; return t; }

    friend ostream& operator<<(ostream& os, const Matrix& m) {
        for (size_t i = 0; i < m.rows(); ++i) {
            os << "[";
            for (size_t j = 0; j < m.cols(); ++j) {
                os << m[i][j] << (j + 1 == m.cols() ? "]\n" : ",");
            }
        }
        return os;
    }

    T det() {
        Matrix<T> C(*this);
        assert(rows() == cols());
        T d = 1;
        size_t n = rows();
        for (size_t i = 0; i < n; ++i) {
            int p = -1;
            for (size_t j = i; j < n; ++j) {
                if (C[j][i] != 0) { p = j; break; }
            }
            if (p == -1) return 0;
            if (i != p) { d = (d * (MOD - 1)) % MOD; swap(C[i], C[p]); }
            d = (d * C[i][i]) % MOD;
            T inv = modinv(C[i][i], MOD);
            for (size_t j = 0; j < n; ++j) C[i][j] = (C[i][j] * inv) % MOD;
            for (size_t j = i + 1; j < n; ++j) {
                T f = C[j][i];
                for (size_t k = 0; k < n; ++k) {
                    C[j][k] = (C[j][k] - C[i][k] * f) % MOD;
                    if (C[j][k] < 0) C[j][k] += MOD;
                }
            }
        }
        return (d % MOD + MOD) % MOD;
    }

private:
    T modinv(T a, T m) {
        T x = 0, y = 1, mm = m;
        if (m == 1) return 0;
        while (a > 1) {
            T q = a / m, t = m;
            m = a % m, a = t;
            t = x, x = y - q * x, y = t;
        }
        if (y < 0) y += mm;
        return y;
    }

public:
    void transform() {
        Matrix<T> Tmp(rows());
        for (size_t i = 0; i < K; ++i) {
            for (size_t j = 0; j < K; ++j) {
                Tmp[i][j] = M[(i + K - 1) % K][(j + K - 1) % K];
            }
            Tmp[i][K] = M[(i + K - 1) % K][K];
            Tmp[K][i] = M[K][(i + K - 1) % K];
        }
        Tmp[K][K] = M[K][K];
        M = move(Tmp.M);
    }
};

Matrix<i64> pre[70][35];

i64 fastpow(i64 b, i64 e) {
    if (e == 0) return 1;
    i64 r = fastpow(b, e / 2);
    r = (r * r) % MOD;
    if (e & 1) r = (r * b) % MOD;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 N_val, K_val;
    cin >> N_val >> K_val;
    K = K_val;

    i64 depth = 0;
    i64 tmp = N_val;
    while (tmp >= K) {
        depth++;
        tmp /= K;
    }

    pre[0][0] = Matrix<i64>::I(K + 1);
    for (int i = 1; i < K + 1; ++i) pre[0][0][0][i] = 1;

    for (int i = 1; i < K; ++i) {
        pre[0][i] = pre[0][i-1];
        pre[0][i].transform();
    }

    for (i64 lvl = 1; lvl <= depth; ++lvl) {
        pre[lvl][0] = pre[lvl-1][0];
        for (int i = 1; i < K; ++i) {
            pre[lvl][0] = pre[lvl-1][i] * pre[lvl][0];
        }
        for (int i = 1; i < K; ++i) {
            pre[lvl][i] = pre[lvl][i-1];
            pre[lvl][i].transform();
        }
    }

    Matrix<i64> res(K + 1, 1);
    res[K][0] = 1;
    int offset = 0;

    while (depth >= 0) {
        for (int i = 0; ; ++i) {
            if (fastpow(K, depth) <= N_val) {
                N_val -= fastpow(K, depth);
                res = pre[depth][offset] * res;
                offset = (offset + 1) % K;
            } else break;
        }
        depth--;
    }

    i64 ans = 0;
    for (int i = 0; i < K + 1; ++i) {
        ans = (ans + res[i][0]) % MOD;
    }
    cout << ans << '\n';

    return 0;
}
